    "passage": "Sam and Emma are good friends. They ride ___1___ bikes to school every day. They are in the same grade, but in different ___2___. Today, when they walk in the school, they see ___3___ students in front of the notice board. Sam asks, “___4___ any new notices today?” “I don’t know. Let’s go to have a look,” Emma says. Then they walk there. “Oh, our school ___5___ two fun activities next month. There is an English speech contest (演讲比赛) and a school party. It sounds great. I’m good at speaking English and I want ___6___ in the activity. What ___7___ you?” Sam says happily. “I can’t speak English well. ___8___ I can sing and dance. I am learning a new song these days. I think I can sing it ___9___ at the party,” Emma says. “Oh, that’s ___10___ bell. Let’s talk about it later,” Sam says. Then they run to the classroom building.",
    "passageHtml": "<p><span class=\"ind\">Sam and Emma are good friends. They ride <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> bikes to school every day. They are in the same grade, but in different <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u>. Today, when they walk in the school, they see <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> students in front of the notice board. Sam asks, “<u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> any new notices today?” “I don’t know. Let’s go to have a look,” Emma says. Then they walk there. “Oh, our school <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> two fun activities next month. There is an English speech contest (演讲比赛) and a school party. It sounds great. I’m good at speaking English and I want <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> in the activity. What <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> you?” Sam says happily. “I can’t speak English well. <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> I can sing and dance. I am learning a new song these days. I think I can sing it <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> at the party,” Emma says. “Oh, that’s <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> bell. Let’s talk about it later,” Sam says. Then they run to the classroom building.</span></p>",
    "intro": "本文主要讲述了Sam和Emma两个好朋友在学校公告板前看到了关于下个月举办英语演讲比赛和校园派对的通知，并分别讨论了自己想要参加的活动。",
