    "passageHtml": "<p><span class=\"ind\">Hello, everyone! My name is Teng Fei, a middle school student <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> Beijing, China. Let me introduce my family to you.</span></p><p><span class=\"ind\">There are five people in my family. My grandparents are very kind, my father is outgoing, <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> my mother is quiet. Dinner time is <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> happiest time of the day. At the table, I usually talk about my school life with them. My grandfather often has fun with his <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> in the park. So he tells us about something interesting they do, like playing <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> chess and going fishing. My grandmother often asks what dishes we want <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> the next day. Then, she can choose good vegetables, meat and fruit in the market.</span></p><p><span class=\"ind\">My parents are both English teachers. Sometimes, they like <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> English with me. Sometimes, we enjoy watching English movies together. These <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> me to learn English well. When I meet some problems and don’t know what to do, they always give me some <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> ways to work them out. With their help and love, I study <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> and never give up.</span></p><p><span class=\"ind\">Family is where life begins and love never ends. I love my family!</span></p>",
