    "passage": "Wuzhizhou Island\n\nAs one of the most famous islands in China, it has bright sunshine, great beaches, blue water and different kinds of water activities.\nLocation: Sanya, Hainan\nOpening hours: 8:00 a. m.-6:30 p. m.\nTickets: 144 yuan/ person (October-April);\n136 yuan/ person (May-September)\nMount Wudang\nIt’s famous for its natural beauty and special culture. You can find high mountains, clear rivers, large rocks and old buildings there.\nLocation: Shiyan, Hubei\nOpening hours: 7:30 a. m.-5:30 p. m.\nTicket: 264 yuan/ person\n\nQiandao Lake\nAs its name shows, the area has more than 1,000 islands. Going boating will be a good choice for you.\nLocation: Hangzhou, Zhejiang\nOpening hours: 8:00 a. m.-2:00 p. m.\nTickets: 150 yuan/ person (March-November);\n120 yuan/ person (December-February)\n\nSouthern Sichuan Bamboo Sea\nIt’s one of the largest natural bamboo forests in the world. When you walk around the bamboo forest, the fresh air helps you relax.\nLocation: Yibin, Sichuan\nOpening hours: 8: 00 a. m-6: 00 p. m.\nTickets: 100 yuan/ person (January-November);\n60 yuan/ person (December)",
