    "passage": "Hello, everyone! I’d love to learn more about what you enjoy doing in your free time. This survey will help Mr Lee plan more interesting after-school activities for next term. Thanks for sharing!\n\nName: Mike White   Class:  4 \nPlease tick (√) your answers.\n1. What is your favourite free-time activity?\n□Building robots.   ☑Playing basketball.   □Programming.\n□Painting or drawing.   □Doing calligraphy.   □Swimming.\n□Playing musical instruments.\nOther:\n2. Why do you enjoy this activity? (You can choose more than one.)\n☑To relax.     □To learn something new.\n□To prepare for future studies.   ☑To spend time with friends.\nOther: To stay healthy.\n3. How often do you do the activity?\n□After school every day.     ☑Two or three times a week.\n□On weekends.     □Once in a while.\nOther:\n4. Would you like to have a “Hobby Sharing Day” in the next class meeting?\n☑Yes, I’d love to!   □Maybe.   □No, I’d prefer not to.",
    "passageHtml": "<div class=\"bx\"><p class=\"ind\">Hello, everyone! I’d love to learn more about what you enjoy doing in your free time. This survey will help Mr Lee plan more interesting after-school activities for next term. Thanks for sharing!</p><img src=\"assets/images/jr_read8a_5_1.png\" width=\"92\" alt=\"\"><br><b>Name:</b> Mike White &emsp; <b>Class:</b> <u>&nbsp;4&nbsp;</u><br><b>Please tick (√) your answers.</b><br>1. What is your favourite free-time activity?<br>□Building robots. &emsp; ☑Playing basketball. &emsp; □Programming.<br>□Painting or drawing. &emsp; □Doing calligraphy. &emsp; □Swimming.<br>□Playing musical instruments.<br>Other:<br>2. Why do you enjoy this activity? (You can choose more than one.)<br>☑To relax. &emsp; &emsp; □To learn something new.<br>□To prepare for future studies. &emsp; ☑To spend time with friends.<br>Other: <u>To stay healthy</u>.<br>3. How often do you do the activity?<br>□After school every day. &emsp; &emsp; ☑Two or three times a week.<br>□On weekends. &emsp; &emsp; □Once in a while.<br>Other:<br>4. Would you like to have a “Hobby Sharing Day” in the next class meeting?<br>☑Yes, I’d love to! &emsp; □Maybe. &emsp; □No, I’d prefer not to.</div>",
