        "ans": "C",
        "exp": "句意：他们的父母用这场旅行给了他们惊喜。根据固定搭配surprise sb. with sth.，主语parents为复数，时态为一般过去时，应选用surprised，表示“使惊喜”。surprise“使惊喜（原形）”；surprises“使惊喜（三单）”，均不符。"
