    "passage": "Have you ever heard of Huang Xuhua, the main designer of China’s first-generation nuclear submarines (第一代核潜艇)? He is known ___1___ the “father of China’s nuclear submarines”. Because of his great achievements, he was given the Medal of the Republic, China’s ___2___ honour, in 2019.\nHuang Xuhua graduated from Shanghai Jiao Tong University in 1949. After graduation, he began to research shipbuilding. At that time, his team didn’t have computers ___3___ technology. They couldn’t get any help from other experts, either. It was almost ___4___ for them to do the research. They ___5___ search for information from magazines and newspapers. After studying the information carefully, they came up with ___6___ own plans. Based on the plans, they made efforts ___7___ experiments (实验) with simple tools. After years of hard work, they ___8___ China’s first nuclear submarine successfully in 1970.\nHuang Xuhua kept researching in his whole life. Even in his 90s, he offered suggestions to young ___9___ on solving technical problems. For us, ___10___ spirit is really worth learning. He passed away on February 6th,2025. Our nation has lost a great scientist. However, we will remember him forever.",
    "passageHtml": "<p><span class=\"ind\">Have you ever heard of Huang Xuhua, the main designer of China’s first-generation nuclear submarines (第一代核潜艇)? He is known <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> the “father of China’s nuclear submarines”. Because of his great achievements, he was given the Medal of the Republic, China’s <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> honour, in 2019.</span></p><p><span class=\"ind\">Huang Xuhua graduated from Shanghai Jiao Tong University in 1949. After graduation, he began to research shipbuilding. At that time, his team didn’t have computers <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> technology. They couldn’t get any help from other experts, either. It was almost <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> for them to do the research. They <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> search for information from magazines and newspapers. After studying the information carefully, they came up with <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> own plans. Based on the plans, they made efforts <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> experiments (实验) with simple tools. After years of hard work, they <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> China’s first nuclear submarine successfully in 1970.</span></p><p><span class=\"ind\">Huang Xuhua kept researching in his whole life. Even in his 90s, he offered suggestions to young <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> on solving technical problems. For us, <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> spirit is really worth learning. He passed away on February 6th,2025. Our nation has lost a great scientist. However, we will remember him forever.</span></p>",
