    "passage": "Yang Zhenning is one of the greatest physicists in the world. He was ___1___ in 1922 and passed away in Beijing in 2025 at ___2___ age of 103.\nYang had a strong love ___3___ science. As a young man, he studied hard and later went to the US for ___4___ education. In 1957, he won the Nobel Prize in Physics with his partner Li Zhengdao. This made ___5___ very famous around the world.\nAs a scientist born in China, he never ___6___ his motherland. He helped build connections between Chinese and American ___7___ . He also raised money to support Chinese young people ___8___ abroad. In 1999, Yang Zhenning returned to Tsinghua University and made a really big ___9___ in the field of science in China.\nWe will ___10___ remember this great man. He not only made great contributions to physics but influenced many young scientists in China.",
    "passageHtml": "<p><span class=\"ind\">Yang Zhenning is one of the greatest physicists in the world. He was <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> in 1922 and passed away in Beijing in 2025 at <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> age of 103.</span></p><p><span class=\"ind\">Yang had a strong love <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> science. As a young man, he studied hard and later went to the US for <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> education. In 1957, he won the Nobel Prize in Physics with his partner Li Zhengdao. This made <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> very famous around the world.</span></p><p><span class=\"ind\">As a scientist born in China, he never <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> his motherland. He helped build connections between Chinese and American <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> . He also raised money to support Chinese young people <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> abroad. In 1999, Yang Zhenning returned to Tsinghua University and made a really big <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> in the field of science in China.</span></p><p><span class=\"ind\">We will <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> remember this great man. He not only made great contributions to physics but influenced many young scientists in China.</span></p><p class=\"ct\"><img src=\"assets/images/jr_gram9a_3_yang.png\" alt=\"Yang Zhenning\" width=\"130\"></p>",
