    "passage": "Have you ever read Fu Lei’s Family Letters? The book came out in 1981. It is a collection of letters ___1___ by Chinese translator Fu Lei. For some years, his son Fu Cong studied abroad. Writing letters became their usual way to communicate ___2___ each other at that time.\nIn some letters, Fu Cong told his father the problems that he met in his life and study. He once asked his father how to choose a music teacher. Fu Lei guided his son patiently ___3___ gave him very good suggestions. In another letter, Fu Cong was praised by ___4___ father after he won an important international piano competition. “I am so proud of you, my dear son. I ___5___ believe that you will have the ability to heal the world with music,” wrote Fu Lei.\nFu Lei also advised Fu Cong ___6___ more Chinese classics. He shared his personal ideas on traditional values with his son. He said, “Everyone should be a great person before becoming ___7___ expert in a certain area. It is even ___8___ than anything else. Otherwise, no matter how much knowledge a person has got, he or she will not achieve real success.”\nA good book can influence a ___9___ whole life. Fu Lei’s Family Letters is a great book ___10___ makes big differences to people who read it. It inspires many young people to live a meaningful life.",
    "passageHtml": "<p><span class=\"ind\">Have you ever read Fu Lei’s Family Letters? The book came out in 1981. It is a collection of letters <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> by Chinese translator Fu Lei. For some years, his son Fu Cong studied abroad. Writing letters became their usual way to communicate <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> each other at that time.</span></p><p><span class=\"ind\">In some letters, Fu Cong told his father the problems that he met in his life and study. He once asked his father how to choose a music teacher. Fu Lei guided his son patiently <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> gave him very good suggestions. In another letter, Fu Cong was praised by <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> father after he won an important international piano competition. “I am so proud of you, my dear son. I <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> believe that you will have the ability to heal the world with music,” wrote Fu Lei.</span></p><p><span class=\"ind\">Fu Lei also advised Fu Cong <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> more Chinese classics. He shared his personal ideas on traditional values with his son. He said, “Everyone should be a great person before becoming <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> expert in a certain area. It is even <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> than anything else. Otherwise, no matter how much knowledge a person has got, he or she will not achieve real success.”</span></p><p><span class=\"ind\">A good book can influence a <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> whole life. Fu Lei’s Family Letters is a great book <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> makes big differences to people who read it. It inspires many young people to live a meaningful life.</span></p>",
