    "passage": "The world itself is becoming much smaller by using modern traffic and modern communication means. Life today is ___1___ easier than it was hundreds of years ago, but it ___2___ new problems. One of the biggest is pollution. To pollute means to make things dirty. Pollution comes in many ways. We ___3___ see it, smell it, drink it and even hear it.\nMan has been polluting the earth. The more people, the more pollution. Many years ago, the problem was not so serious ___4___ there were not so many people. When the land was used up or the river was dirty in a place, men moved to another place. But this is no longer true. Man is slowly polluting ___5___ whole world.\nAir pollution is still the most serious. It’s bad to all living ___6___ in the world, but there is not only one kind of pollution. Water pollution kills our fish and pollutes our drinking water. Noise pollution makes us ___7___ angry more easily.\nMany countries are making rules to fight pollution. They stop people from ___8___ coal in houses and factories in the city, and from blowing dirty smoke into the air.\nThe pollution of SO2 is now the most dangerous problem of air pollution. It ___9___ by heavy traffic. It is certain that if there are fewer people driving, there will be less air pollution.\nThe earth is ___10___ home. We must take care of it. That means keeping the land, water and air clean. And we must be careful of the rise in population at the same time.",
    "passageHtml": "<p><span class=\"ind\">The world itself is becoming much smaller by using modern traffic and modern communication means. Life today is <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> easier than it was hundreds of years ago, but it <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> new problems. One of the biggest is pollution. To pollute means to make things dirty. Pollution comes in many ways. We <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> see it, smell it, drink it and even hear it.</span></p><p><span class=\"ind\">Man has been polluting the earth. The more people, the more pollution. Many years ago, the problem was not so serious <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> there were not so many people. When the land was used up or the river was dirty in a place, men moved to another place. But this is no longer true. Man is slowly polluting <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> whole world.</span></p><p><span class=\"ind\">Air pollution is still the most serious. It’s bad to all living <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> in the world, but there is not only one kind of pollution. Water pollution kills our fish and pollutes our drinking water. Noise pollution makes us <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> angry more easily.</span></p><p><span class=\"ind\">Many countries are making rules to fight pollution. They stop people from <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> coal in houses and factories in the city, and from blowing dirty smoke into the air.</span></p><p><span class=\"ind\">The pollution of SO2 is now the most dangerous problem of air pollution. It <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> by heavy traffic. It is certain that if there are fewer people driving, there will be less air pollution.</span></p><p><span class=\"ind\">The earth is <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> home. We must take care of it. That means keeping the land, water and air clean. And we must be careful of the rise in population at the same time.</span></p>",
