    "passage": "Bob always dreamed of being successful in science like his father. His father told him that he could make his dream come true by ___1___ math, physics and chemistry well. Although he studied hard in these subjects, he didn’t pass his physics exam ___2___ . He was so sad and he thought his dream wouldn’t come true. ___3___ bad thing!\nOne day, when he arrived home, his mother are preparing. He expressed his sadness ___4___ his mother. After a while, his mother handed him a peanut (花生) and said, “Pinch (捏) it hard.” Bob did so, and the shell (壳) of the peanut was broken easily, leaving a peanut kernel (核)\nThen, he ___5___ to pinch the kernel by his mother again. As a result, the red skin left the peanut kernel, leaving only white fruit. Bob’s mother asked him to pinch the fruit a bit ___6___ than just now. Bob didn’t know ___7___ his mother told him to do so, but he still did it. However, no matter how hard he tried, he didn’t crushed (捏碎) the white fruit. How he wished he could make it!\nFinally, his mother talked to him with ___8___ , “In daily life, some problems are difficult ___9___ out. But if we have a strong heart, we ___10___ a chance to solve them.”\nBob understood that he shouldn’t lose heart. He thanked his mother deeply and took his physics paper out.",
    "passageHtml": "<p><span class=\"ind\">Bob always dreamed of being successful in science like his father. His father told him that he could make his dream come true by <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> math, physics and chemistry well. Although he studied hard in these subjects, he didn’t pass his physics exam <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> . He was so sad and he thought his dream wouldn’t come true. <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> bad thing!</span></p><p><span class=\"ind\">One day, when he arrived home, his mother are preparing. He expressed his sadness <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> his mother. After a while, his mother handed him a peanut (花生) and said, “Pinch (捏) it hard.” Bob did so, and the shell (壳) of the peanut was broken easily, leaving a peanut kernel (核)</span></p><p><span class=\"ind\">Then, he <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> to pinch the kernel by his mother again. As a result, the red skin left the peanut kernel, leaving only white fruit. Bob’s mother asked him to pinch the fruit a bit <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> than just now. Bob didn’t know <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> his mother told him to do so, but he still did it. However, no matter how hard he tried, he didn’t crushed (捏碎) the white fruit. How he wished he could make it!</span></p><p><span class=\"ind\">Finally, his mother talked to him with <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> , “In daily life, some problems are difficult <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> out. But if we have a strong heart, we <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> a chance to solve them.”</span></p><p><span class=\"ind\">Bob understood that he shouldn’t lose heart. He thanked his mother deeply and took his physics paper out.</span></p>",
