    "title": "九上语法选择 · 十 孔子论孔圉不耻下问",
    "passage": "Confucius (孔子) was well-known. He was ___1___ great thinker, teacher, and politician (政治家). He was wise and enjoyed learning ___2___ he always asked for help from different people. He never stopped ___3___ questions and looking for advice.\nThere was ___4___ wise man Kong Yu who lived at the same time as Confucius. Kong Yu worked for the government in a place called Wei. He was not only clever but also very humble (谦逊的). He did many important things for Wei. ___5___ he died, the ruler of Wei wanted everyone to remember and learn from his love for learning. So, Kong Yu ___6___ the title “Wen”.\nPeople started calling Kong Yu “Kong Wenzi” to show respect. One of Confucius’ ___7___ , Zigong, was from Wei, too. He wasn’t happy with the title given to Kong Yu. He asked Confucius, “Teacher, Kong Yu is smart, but there must be many other people who are ___8___ than him. Why did he get that title?”\nConfucius smiled and answered ___9___ , “Kong Yu was smart and worked very hard. He could get the title because he was never ashamed to ask for help, even from people who were less knowledgeable than him. And that’s what made ___10___ different.” Finally, Zigong realized that Kong Yu should get the honor because he was humble and always ready to learn.\nAnd that’s the story of “bu chi xia wen”. It teaches us to be humble and keep looking for knowledge.",
    "passageHtml": "<p><span class=\"ind\">Confucius (孔子) was well-known. He was <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> great thinker, teacher, and politician (政治家). He was wise and enjoyed learning <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> he always asked for help from different people. He never stopped <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> questions and looking for advice.</span></p><p><span class=\"ind\">There was <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> wise man Kong Yu who lived at the same time as Confucius. Kong Yu worked for the government in a place called Wei. He was not only clever but also very humble (谦逊的). He did many important things for Wei. <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> he died, the ruler of Wei wanted everyone to remember and learn from his love for learning. So, Kong Yu <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> the title “Wen”.</span></p><p><span class=\"ind\">People started calling Kong Yu “Kong Wenzi” to show respect. One of Confucius’ <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> , Zigong, was from Wei, too. He wasn’t happy with the title given to Kong Yu. He asked Confucius, “Teacher, Kong Yu is smart, but there must be many other people who are <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> than him. Why did he get that title?”</span></p><p><span class=\"ind\">Confucius smiled and answered <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> , “Kong Yu was smart and worked very hard. He could get the title because he was never ashamed to ask for help, even from people who were less knowledgeable than him. And that’s what made <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> different.” Finally, Zigong realized that Kong Yu should get the honor because he was humble and always ready to learn.</span></p><p><span class=\"ind\">And that’s the story of “bu chi xia wen”. It teaches us to be humble and keep looking for knowledge.</span></p>",
