    "passage": "Lily is a 15-year-old girl from America. She fell in love with Chinese oil paper umbrellas at ___1___ art fair last year. As soon as she saw them, she was drawn to the beautiful pictures on the umbrellas. ___2___ wonderful they were!\nSince then, she has spent much time searching for information about ___3___ online. She knows the umbrellas ___4___ of bamboo and oil paper and that they are a symbol of traditional Chinese art and culture. To Lily’s surprise, it requires over 100 steps ___5___ an oil paper umbrella!\nAmazed by the skills and the stories behind the umbrella, Lily used to wonder ___6___ she could have her own oil paper umbrella. And she finally got one this May. She loves it so much ___7___ takes great care of it. She often takes walks in the park holding the umbrella. She takes pride ___8___ having such a special piece of artwork.\nNext Wednesday, Lily’s class ___9___ a discussion about China. She is going to talk about the beauty of Chinese oil paper umbrellas so that her classmates can learn even ___10___ about traditional Chinese art and culture.",
    "passageHtml": "<p><span class=\"ind\">Lily is a 15-year-old girl from America. She fell in love with Chinese oil paper umbrellas at <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> art fair last year. As soon as she saw them, she was drawn to the beautiful pictures on the umbrellas. <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> wonderful they were!</span></p><p><span class=\"ind\">Since then, she has spent much time searching for information about <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> online. She knows the umbrellas <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> of bamboo and oil paper and that they are a symbol of traditional Chinese art and culture. To Lily’s surprise, it requires over 100 steps <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> an oil paper umbrella!</span></p><p><span class=\"ind\">Amazed by the skills and the stories behind the umbrella, Lily used to wonder <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> she could have her own oil paper umbrella. And she finally got one this May. She loves it so much <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> takes great care of it. She often takes walks in the park holding the umbrella. She takes pride <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> having such a special piece of artwork.</span></p><p><span class=\"ind\">Next Wednesday, Lily’s class <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> a discussion about China. She is going to talk about the beauty of Chinese oil paper umbrellas so that her classmates can learn even <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> about traditional Chinese art and culture.</span></p>",
