    "passage": "People nowadays are often surprised at the speed of China’s high speed trains. Slow trains, however, are still a lifeline for many people in ___1___ countryside.\nThe two slow trains, No. 5640 and No. 5639, run between Guiyang and Yuping, two cities in Guizhou Province. It is reported ___2___ Train No. 5640 sets out from Guiyang. It runs through big stations like Kaili and Zhenyuan, ___3___ stops at small ones in ethnic minority (少数民族) villages. Train No. 5639 runs in the opposite direction.\nEach train travels about 337 kilometers and takes more than seven ___4___ . It connects more than 100 ethnic minority villages along the line. And the ___5___ ticket price is only six yuan.\nThe trains have been the important transportation tools for villagers living along the line. The trains are used to ___6___ farm products to cities.\nHu Guichuan, a conductor (列车长), ___7___ on the slow trains for over 26 years. ___8___ villagers sell farm products, he builds a market on the train. Villagers are allowed to sell ___9___ goods to passengers and provide passengers with a special travel experience. Hu also puts a board on the train. On it, villagers can get the latest price information. “ ___10___ helpful trains they are! I hope these slow, cheap and convenient trains can run forever.” Hu says.",
