    "passage": "When I was 15, I became very interested in shopping. After being just a buyer for a while, I wanted to sell something. I had many things that I no longer needed at home. I knew ___1___ the help of my father I could make money. So for months and months I enjoyed myself by ___2___ things on my dad’s bank account.\nOn July 18th, 2015, I made my own account and began ___3___ my own business. Things were going well and then I realized ___4___ selling things around the house wasn’t enough for me, so I decided to expand (扩大) my business by running a resale shop. I went around to the yard sales and bought things at low prices and sold them at ___5___ prices to make money.\nLast October, I went to a yard sale. A lady had many nice things to sell. I went up to her ___6___ we had a conversation. Through the communication, I knew she needed money to feed her family. I thought I could do it ___7___ and more quickly for her. So I made a decision to help her out. She looked at ___8___ for a while and then said yes. After that I took away some of her things and over the next month I made ￥1,500 for her! When I gave her the money, she broke into tears. I have never ___9___ so pleased to help someone in my life. I know my skills ___10___ be used to help those in need. And sometimes just because of one small act of kindness, I could make a big difference to others.",
    "passageHtml": "<p><span class=\"ind\">When I was 15, I became very interested in shopping. After being just a buyer for a while, I wanted to sell something. I had many things that I no longer needed at home. I knew <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> the help of my father I could make money. So for months and months I enjoyed myself by <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> things on my dad’s bank account.</span></p><p><span class=\"ind\">On July 18th, 2015, I made my own account and began <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> my own business. Things were going well and then I realized <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> selling things around the house wasn’t enough for me, so I decided to expand (扩大) my business by running a resale shop. I went around to the yard sales and bought things at low prices and sold them at <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> prices to make money.</span></p><p><span class=\"ind\">Last October, I went to a yard sale. A lady had many nice things to sell. I went up to her <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> we had a conversation. Through the communication, I knew she needed money to feed her family. I thought I could do it <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> and more quickly for her. So I made a decision to help her out. She looked at <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> for a while and then said yes. After that I took away some of her things and over the next month I made ￥1,500 for her! When I gave her the money, she broke into tears. I have never <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> so pleased to help someone in my life. I know my skills <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> be used to help those in need. And sometimes just because of one small act of kindness, I could make a big difference to others.</span></p>",
