    "title": "九上语法选择 · 十七 树叶雕刻艺术与生活美学",
    "passage": "Leaf-cutting art is a kind of art work, like Chinese paper cutting.\nIn autumn and winter, many streets ___1___ with fallen leaves. Most of us probably just pass over them without paying much attention, but not Kanat Nurtazin, an artist from Kazakhstan. Do you know ___2___ ? He will pick up some fallen leaves and cut beautiful artworks out of them.\nKanat works at a university. He ___3___ drawing as a hobby to stay creative since 2013.This long-time hobby has also allowed him to express himself through art and made him popular. ___4___ meaningful hobby it was!\nIn 2013, Kanat started a project called “100 Methods of Drawing”. In this project, he tries to use different materials and skills for artworks. ___5___ all these creative paintings, leaf-cutting art is one of his favorites. To make leaf art, Kanat first chooses a leaf from his collection. Then, he ___6___ imagines a funny story or a lively moment. He draws ___7___ on a piece of paper and sticks the paper to the leaf. After the glue dries, Kanat uses a razor (剃须刀) to cut out the pattern on the leaf. This job needs ___8___ time of all the work.\nA ___9___ life is short. If you look at it with your creative eyes, like Kanat does, you can also give the leaf a ___10___ life by making it tell an interesting story!\nAs the saying goes, “Beauty is not lacking in life, but rather the eyes to discover it.” Let’s enjoy the world with a pair of creative eyes.",
    "passageHtml": "<p><span class=\"ind\">Leaf-cutting art is a kind of art work, like Chinese paper cutting.</span></p><p><span class=\"ind\">In autumn and winter, many streets <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> with fallen leaves. Most of us probably just pass over them without paying much attention, but not Kanat Nurtazin, an artist from Kazakhstan. Do you know <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> ? He will pick up some fallen leaves and cut beautiful artworks out of them.</span></p><p><span class=\"ind\">Kanat works at a university. He <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> drawing as a hobby to stay creative since 2013.This long-time hobby has also allowed him to express himself through art and made him popular. <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> meaningful hobby it was!</span></p><p><span class=\"ind\">In 2013, Kanat started a project called “100 Methods of Drawing”. In this project, he tries to use different materials and skills for artworks. <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> all these creative paintings, leaf-cutting art is one of his favorites. To make leaf art, Kanat first chooses a leaf from his collection. Then, he <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> imagines a funny story or a lively moment. He draws <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> on a piece of paper and sticks the paper to the leaf. After the glue dries, Kanat uses a razor (剃须刀) to cut out the pattern on the leaf. This job needs <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> time of all the work.</span></p><p><span class=\"ind\">A <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> life is short. If you look at it with your creative eyes, like Kanat does, you can also give the leaf a <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> life by making it tell an interesting story!</span></p><p><span class=\"ind\">As the saying goes, “Beauty is not lacking in life, but rather the eyes to discover it.” Let’s enjoy the world with a pair of creative eyes.</span></p>",
    "intro": "本文通过介绍哈萨克斯坦的一位艺术家Kanat Nurtazin的叶子雕刻艺术，表达了即使在普通的事物中也能发现美与艺术的理念。",
