    "title": "九上语法选择 · 十八 广式早茶文化",
    "passage": "Having Zao Cha, or morning tea, is a typical morning activity for people in Guangdong. Whether rich or poor, young or old, locals go to morning tea houses to drink tea or enjoy dim sum (点心) for breakfast. For them, ___1___ Zao Cha is not just a daily habit but also ___2___ important way of social communication.\nGuangdong morning tea dates back to the Qing Dynasty. It began ___3___ a small restaurant in Guangzhou called “Yi Li Guan”, which served tea and dim sum. Over time, more and more ___4___ tea houses appeared, and since then, Cantonese (广州的) people ___5___ the habit of drinking morning tea in tea houses.\nToday, on weekends or holidays, the whole family or good friends often get together for morning tea. It’s ___6___ an enjoyable way to pass time and relax completely.\nIn morning tea, tea is a necessary part. The Cantonese prefer black tea ___7___ it warms the stomach and helps digestion (消化). Although a little bitter and ___8___ clear than green tea, it pairs perfectly with dim sum during morning tea. In addition, the Cantonese think ___9___ Oolong tea, Tieguanyin tea and pu’er tea are also popular choices.\nThe morning tea culture is not only popular in Guangdong, but has also become a global trend (全球趋势). Thanks to the increasing number of overseas Chinese, Cantonese morning tea restaurants can now be found ___10___ in big cities like New York and even on some small islands in the South Pacific Ocean.",
    "passageHtml": "<p><span class=\"ind\">Having Zao Cha, or morning tea, is a typical morning activity for people in Guangdong. Whether rich or poor, young or old, locals go to morning tea houses to drink tea or enjoy dim sum (点心) for breakfast. For them, <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> Zao Cha is not just a daily habit but also <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> important way of social communication.</span></p><p><span class=\"ind\">Guangdong morning tea dates back to the Qing Dynasty. It began <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> a small restaurant in Guangzhou called “Yi Li Guan”, which served tea and dim sum. Over time, more and more <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> tea houses appeared, and since then, Cantonese (广州的) people <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> the habit of drinking morning tea in tea houses.</span></p><p><span class=\"ind\">Today, on weekends or holidays, the whole family or good friends often get together for morning tea. It’s <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> an enjoyable way to pass time and relax completely.</span></p><p><span class=\"ind\">In morning tea, tea is a necessary part. The Cantonese prefer black tea <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> it warms the stomach and helps digestion (消化). Although a little bitter and <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> clear than green tea, it pairs perfectly with dim sum during morning tea. In addition, the Cantonese think <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> Oolong tea, Tieguanyin tea and pu’er tea are also popular choices.</span></p><p><span class=\"ind\">The morning tea culture is not only popular in Guangdong, but has also become a global trend (全球趋势). Thanks to the increasing number of overseas Chinese, Cantonese morning tea restaurants can now be found <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> in big cities like New York and even on some small islands in the South Pacific Ocean.</span></p>",
