    "passage": "A new game is becoming popular with young people: tens or even hundreds of people come together, choose to be “cats” or “mice”, share locations on their phone, and then play hide-and-seek in a big open-air space.\nYoung people said ___1___ this game not only gets people to exercise but also throw ___2___ into the joys of childhood memories. It helps with stress and turns running into a fun social game.\nOn September 24th, I went to experience the activity with Patrick McCarthy, a writer for Teens, at the Olympic Forest Parkin Beijing. There were around 30 people. Most of us didn’t know each other. The game had ___3___ rounds（轮）. In the first round, five people were “cats” and the rest were “mice”. With five minutes for “mice” to run and hide, the “cats” found them by ___4___ the locations they share on a map app. The second round was group competition.\nWe all played hide-and-seek when we were little. When I invited McCarthy, he wondered, “What’s the point of playing this game as a grown-up?”\nIt turned out to be a joyful experience for him. The use of GPS made this childhood game ___5___ more fun. “It was a creative way of bringing something new ___6___ old games with technology.” said McCarthy. “It is a good way ___7___ new people and even make friends, as one needs to work together with new people.”\nFor me, it’s good that this activity got me moving as I am not so ___8___ in working out in my daily life. However, I could have had more fun if the park wasn’t so big. When I saw the “mice” were so far away from me, I just wanted to ___9___ . On ___10___ hand, when it made it difficult for me to get caught, I felt less excited.",
