    "passage": "For some teenagers, being an adult is the ___1___ thing in the world. Adults don’t need to do homework or take exams. They do what they like and make money. How ___2___ ! But is it true?\nLast month,Grade Seven students at Sunshine School had a taste of the adult world. The teachers asked them ___3___ a piece of special homework called “Working with your parents for one day”.\nWujing’s mother works as ___4___ ticket collector in a park. At 6 am,the 14-year-old girl set out for work with her mother. It was dark and cold. Before the park opened, they did some cleaning and prepared for the ___5___ coming. When the visitors came, they greeted with a smile. After standing for the whole day, Wu felt worn out.\n“She is busier and more tired than what I thought. I should help her more.”said Wu.\nLi Shiyi, 14 , spent the whole day helping in a car. ___6___ father is a taxi driver. She had to pick calls and ___7___ change back. Li thought it would be easy to work in a car. ___8___ soon she found that they didn’t even have time ___9___ lunch.\n“Now I know how ___10___ it is to make money,” Li said. “We should care for our parents more and never waste money.",
    "passageHtml": "<p><span class=\"ind\">For some teenagers, being an adult is the <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> thing in the world. Adults don’t need to do homework or take exams. They do what they like and make money. How <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> ! But is it true?</span></p><p><span class=\"ind\">Last month,Grade Seven students at Sunshine School had a taste of the adult world. The teachers asked them <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> a piece of special homework called “Working with your parents for one day”.</span></p><p><span class=\"ind\">Wujing’s mother works as <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> ticket collector in a park. At 6 am,the 14-year-old girl set out for work with her mother. It was dark and cold. Before the park opened, they did some cleaning and prepared for the <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> coming. When the visitors came, they greeted with a smile. After standing for the whole day, Wu felt worn out.</span></p><p><span class=\"ind\">“She is busier and more tired than what I thought. I should help her more.”said Wu.</span></p><p><span class=\"ind\">Li Shiyi, 14 , spent the whole day helping in a car. <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> father is a taxi driver. She had to pick calls and <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> change back. Li thought it would be easy to work in a car. <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> soon she found that they didn’t even have time <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> lunch.</span></p><p><span class=\"ind\">“Now I know how <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> it is to make money,” Li said. “We should care for our parents more and never waste money.</span></p>",
