    "passage": "On a cold winter morning, Mamothy, the lead elephant, set out with her family for breakfast. The cold weather made ___1___ difficult to find food in the wild. So Mamothy decided to take them to the village where humans lived. When they reached the village, they were ___2___ .\n“Wow! Look! There are so many flowers in this place! How big and colorful they are!” the baby elephants said ___3___ .\n“They don’t look like real flowers. Let me find out ___4___ they are before we eat them,” Mamothy told everyone. Suddenly, she saw ___5___ cow and went to ask her.\n“I’m sorry to trouble you, but could you please tell me what ___6___ ?” Mamothy asked when pointing to the colorful things. “Is it safe ___7___ them?”\n“Oh no! Don’t eat them! Humans call them plastic（塑料的）bags. They throw them in a dump nearby. But the wind spreads them all around. You may choke（窒息）to death ___8___ you eat them.” answered the cow.\n“How terrible! Thank you for ___9___ me this.” Mamothy went back to her family and told everyone the news.\nThen Mamothy said, “Humans’ world is too dangerous now but it used to ___10___ so safe! What a pity! Tomorrow, we shall all go to another place to look for food.” All the elephants agreed and then they seldom set foot on the village.",
    "passageHtml": "<p><span class=\"ind\">On a cold winter morning, Mamothy, the lead elephant, set out with her family for breakfast. The cold weather made <u>&nbsp;&nbsp;1&nbsp;&nbsp;</u> difficult to find food in the wild. So Mamothy decided to take them to the village where humans lived. When they reached the village, they were <u>&nbsp;&nbsp;2&nbsp;&nbsp;</u> .</span></p><p><span class=\"ind\">“Wow! Look! There are so many flowers in this place! How big and colorful they are!” the baby elephants said <u>&nbsp;&nbsp;3&nbsp;&nbsp;</u> .</span></p><p><span class=\"ind\">“They don’t look like real flowers. Let me find out <u>&nbsp;&nbsp;4&nbsp;&nbsp;</u> they are before we eat them,” Mamothy told everyone. Suddenly, she saw <u>&nbsp;&nbsp;5&nbsp;&nbsp;</u> cow and went to ask her.</span></p><p><span class=\"ind\">“I’m sorry to trouble you, but could you please tell me what <u>&nbsp;&nbsp;6&nbsp;&nbsp;</u> ?” Mamothy asked when pointing to the colorful things. “Is it safe <u>&nbsp;&nbsp;7&nbsp;&nbsp;</u> them?”</span></p><p><span class=\"ind\">“Oh no! Don’t eat them! Humans call them plastic（塑料的）bags. They throw them in a dump nearby. But the wind spreads them all around. You may choke（窒息）to death <u>&nbsp;&nbsp;8&nbsp;&nbsp;</u> you eat them.” answered the cow.</span></p><p><span class=\"ind\">“How terrible! Thank you for <u>&nbsp;&nbsp;9&nbsp;&nbsp;</u> me this.” Mamothy went back to her family and told everyone the news.</span></p><p><span class=\"ind\">Then Mamothy said, “Humans’ world is too dangerous now but it used to <u>&nbsp;&nbsp;10&nbsp;&nbsp;</u> so safe! What a pity! Tomorrow, we shall all go to another place to look for food.” All the elephants agreed and then they seldom set foot on the village.</span></p>",
