    "title": "七上A篇 · 一 奥运跳水冠军全红婵",
    "passage": "The 2024 Paris Olympic Games were over. China’s Olympic team won 91 medals (奖牌), including 40 gold, 27 sliver and 24 bronze. All eyes are on the Chinese diving dream team (中国跳水梦之队). For the first time, it won all eight gold medals in the diving (跳水) events of the Olympics. In the team, Quan Hongchan stood out with her wonderful diving.\n\nWhen Quan was just seven, she started to learn diving. The diving platform (跳台) is very high and she is still so young. Sometimes she is afraid of it, but she always tries her best. Quan practices for eight hours every day, but she never complains (抱怨) about the training from day to night. In the women’s 10-meter platform final, she won gold again, just as she did in Tokyo Olympics.\n\nQuan told the reporter (记者), “Everyone says I am a genius (天才). But I think it’s more about hard-working. I must practice over and over again. Practice makes perfect. That’s me, Quan Hongchan, from China.”",
    "passageHtml": "<p><span class=\"ind\">The 2024 Paris Olympic Games were over. China’s Olympic team won 91 medals (奖牌), including 40 gold, 27 sliver and 24 bronze. All eyes are on the Chinese diving dream team (中国跳水梦之队). For the first time, it won all eight gold medals in the diving (跳水) events of the Olympics. In the team, Quan Hongchan stood out with her wonderful diving.</span></p><p><span class=\"ind\">When Quan was just seven, she started to learn diving. The diving platform (跳台) is very high and she is still so young. Sometimes she is afraid of it, but she always tries her best. Quan practices for eight hours every day, but she never complains (抱怨) about the training from day to night. In the women’s 10-meter platform final, she won gold again, just as she did in Tokyo Olympics.</span></p><p><span class=\"ind\">Quan told the reporter (记者), “Everyone says I am a genius (天才). But I think it’s more about hard-working. I must practice over and over again. Practice makes perfect. That’s me, Quan Hongchan, from China.”</span></p>",
