    "title": "七上A篇 · 五 Lisa的新家与卧室",
    "passage": "I’m Lisa. Good news! Good news! We have a new house. The rooms are small but they are all nice. There are many rooms in our new house.\n\nMy bedroom is my favorite room in our house. I make the room full of green color because I like green best. First, I paint the wall green. Then I put some pictures on the wall. The pictures are all about plants, flowers and the sky. I put a big red bed in the middle of the room. The quilt is like a big tree. You can see a bird sleeping in the tree. There is a green table on the left side of the bed. And there is a green desk on the right side of the bed. I am so happy because there are many storybooks on it. I love reading very much. Reading makes me wise. There is a big orange bookcase in the room. I also put my things in the bookcase: my schoolbag, CDs, history books, and the model plane.\n\nMy second favorite room is the kitchen because I like cooking. My mother is a good cook, so I want to be a cook.\n\nI love my new house. Welcome to my new house.",
    "passageHtml": "<p><span class=\"ind\">I’m Lisa. Good news! Good news! We have a new house. The rooms are small but they are all nice. There are many rooms in our new house.</span></p><p><span class=\"ind\">My bedroom is my favorite room in our house. I make the room full of green color because I like green best. First, I paint the wall green. Then I put some pictures on the wall. The pictures are all about plants, flowers and the sky. I put a big red bed in the middle of the room. The quilt is like a big tree. You can see a bird sleeping in the tree. There is a green table on the left side of the bed. And there is a green desk on the right side of the bed. I am so happy because there are many storybooks on it. I love reading very much. Reading makes me wise. There is a big orange bookcase in the room. I also put my things in the bookcase: my schoolbag, CDs, history books, and the model plane.</span></p><p><span class=\"ind\">My second favorite room is the kitchen because I like cooking. My mother is a good cook, so I want to be a cook.</span></p><p><span class=\"ind\">I love my new house. Welcome to my new house.</span></p>",
    "intro": "本文主要介绍了Lisa的新房子。",
