    "title": "七上A篇 · 七 2023珠海马拉松赛",
    "passage": "Do you know the marathon (马拉松)? It’s a long running race of 42 km. The 2023 Zhuhai Marathon is on November 26th. Over 10,000 runners from across China and the world take part in it.\n\nIt begins at 7:30 AM at Zhuhai Sports Center. The fastest runners begin running first, and the others run behind them. When they are running, they can see some famous places and buildings, such as Zhuhai Library, Zhuhai Opera House, and Hong Kong—Zhuhai—Macao Bridge. It ends at Lvyangwan, a beautiful beach park.\n\nIt takes the winners about 2 hours to finish the race. Most people need 3 or 4 hours. Many families bring their kids to join in the running. They only run 6 km. They just run for fun, so people call it Fun Run.\n\nRunning makes the runners sweat a lot. Along the way, they pick up cups of water to drink or to pour over their heads, to cool down. It’s good for them to eat some bread, rice and potatoes after the race.\n\nThe Zhuhai Marathon is not just about running. It brings people together, shows our beautiful city to the world, and calls for a healthy lifestyle. Do you want to join in the marathon next year? You can visit its website at www.zhuhai-marathon.com.",
    "passageHtml": "<p><span class=\"ind\">Do you know the marathon (马拉松)? It’s a long running race of 42 km. The 2023 Zhuhai Marathon is on November 26th. Over 10,000 runners from across China and the world take part in it.</span></p><p><span class=\"ind\">It begins at 7:30 AM at Zhuhai Sports Center. The fastest runners begin running first, and the others run behind them. When they are running, they can see some famous places and buildings, such as Zhuhai Library, Zhuhai Opera House, and Hong Kong—Zhuhai—Macao Bridge. It ends at Lvyangwan, a beautiful beach park.</span></p><p><span class=\"ind\">It takes the winners about 2 hours to finish the race. Most people need 3 or 4 hours. Many families bring their kids to join in the running. They only run 6 km. They just run for fun, so people call it Fun Run.</span></p><p><span class=\"ind\">Running makes the runners sweat a lot. Along the way, they pick up cups of water to drink or to pour over their heads, to cool down. It’s good for them to eat some bread, rice and potatoes after the race.</span></p><p><span class=\"ind\">The Zhuhai Marathon is not just about running. It brings people together, shows our beautiful city to the world, and calls for a healthy lifestyle. Do you want to join in the marathon next year? You can visit its website at www.zhuhai-marathon.com.</span></p>",
