    "passage": "Hello! My name is Jack, an American boy. Now I’m in a middle school in Beijing. This week, I am busy in my new school because we have a lot of activities.\n\nOn Monday, we have a School & Family Day. On that day, parents come to school to take part in our activities. My parents are in New York, so my uncle and aunt come to school to help me. How kind they are!\n\nOn Wednesday, we have a school sale (销售活动) in the morning. At the school sale, students can buy different kinds of things from each other. Li Ming buys a black cap and it looks cool. Chen Lin buys a T-shirt from Lu Wen. I buy a toy bus from Zhang Wei and a book from Liu Xia. In the afternoon, we have a soccer game. Many of my classmates can play it well. In the end, we win the game. We are very happy!\n\nOn Sunday, our class go to the beach(海滩). Our Chinese teacher, Ms. Chen, goes with us. She is so nice, we all like her very much. This is a busy but happy week.",
