    "title": "七上A篇 · 十三 与家人和睦相处的三点建议",
    "passage": "Family is the most important（重要的） to all of us. But many of us don’t understand（理解） this. We have problems with our family members. How can we get on well with our family members? Here are three tips（小建议）.\n\nFirst, spend（花） more time with them. Don’t spend too much time playing computer games. You can ask one of your family members to play with you—your dad, mom, grandpa or grandma. If they are busy, sometimes you can even play with your aunt, uncle or their daughters and sons.\n\nSecond, share（分享） your feelings and ask for help. You want your family members to help you when you’re unhappy, but they may not know that. Tell them what has happened（发生） and you’ll be glad（高兴的）after that.\n\nAt last, do your best at what you do. When you do your best, you make your family happy. Why? Because it lets them know you’re good and they have a great kid.",
    "passageHtml": "<p><span class=\"ind\">Family is the most important（重要的） to all of us. But many of us don’t understand（理解） this. We have problems with our family members. How can we get on well with our family members? Here are three tips（小建议）.</span></p><p><span class=\"ind\">First, spend（花） more time with them. Don’t spend too much time playing computer games. You can ask one of your family members to play with you—your dad, mom, grandpa or grandma. If they are busy, sometimes you can even play with your aunt, uncle or their daughters and sons.</span></p><p><span class=\"ind\">Second, share（分享） your feelings and ask for help. You want your family members to help you when you’re unhappy, but they may not know that. Tell them what has happened（发生） and you’ll be glad（高兴的）after that.</span></p><p><span class=\"ind\">At last, do your best at what you do. When you do your best, you make your family happy. Why? Because it lets them know you’re good and they have a great kid.</span></p>",
