    "passage": "Elsa and Anna are sisters. They are from an interesting film FrozenⅡ(《冰雪奇缘2》). In the film, Elsa,the queen of Arendelle, defeats（打败） the bad guys with the help of Anna finally. In this film, they wear trousers. And the two girls are in trouble again. There is something wrong with Elsa’s magical powers（魔力）.This puts her homeland in danger（危险）. One day, Elsa with Anna goes to find where her magical powers come from. On their way, they meet some friends. Now let’s know more about them.\n\nElsaShe is beautiful. She has long hair. She was born with strong magical powers, but sometimes they bring her some trouble.\nAnnaShe’s Elsa’s younger sister. She always looks happy. When Elsa is in danger, she tries to help Elsa.\nKristoffHe’s a strong ice harvester（采冰者） . He’s always there for the girls.\nOlafHe’s a cute snowman. Elsa makes him with her magical powers.",
    "passageHtml": "<p><span class=\"ind\">Elsa and Anna are sisters. They are from an interesting film FrozenⅡ(《冰雪奇缘2》). In the film, Elsa,the queen of Arendelle, defeats（打败） the bad guys with the help of Anna finally. In this film, they wear trousers. And the two girls are in trouble again. There is something wrong with Elsa’s magical powers（魔力）.This puts her homeland in danger（危险）. One day, Elsa with Anna goes to find where her magical powers come from. On their way, they meet some friends. Now let’s know more about them.</span></p><div style=\"overflow-x:auto;margin:10px 0\"><table style=\"width:100%;border-collapse:collapse;border:1px solid var(--bd);font-size:13px\"><tr><td style=\"border:1px solid var(--bd);padding:6px 10px;text-align:center\">ElsaShe is beautiful. She has long hair. She was born with strong magical powers, but sometimes they bring her some trouble.</td></tr><tr><td style=\"border:1px solid var(--bd);padding:6px 10px;text-align:center\">AnnaShe’s Elsa’s younger sister. She always looks happy. When Elsa is in danger, she tries to help Elsa.</td></tr><tr><td style=\"border:1px solid var(--bd);padding:6px 10px;text-align:center\">KristoffHe’s a strong ice harvester（采冰者） . He’s always there for the girls.</td></tr><tr><td style=\"border:1px solid var(--bd);padding:6px 10px;text-align:center\">OlafHe’s a cute snowman. Elsa makes him with her magical powers.</td></tr></table></div>",
